using NUnit.Framework;
using System.Collections.Generic;

[TestFixture]
public class CountFrequenciesTests
{
    [Test]
    public void Counts_Number_Frequency()
    {
        var result = CountFrequencies(new[] { 1, 2, 2, 3, 1, 1 });
        Assert.That(result[1], Is.EqualTo(3));
        Assert.That(result[2], Is.EqualTo(2));
        Assert.That(result[3], Is.EqualTo(1));
    }

    private Dictionary<int, int> CountFrequencies(int[] nums)
    {
        var counts = new Dictionary<int, int>();

        foreach (var num in nums)
            counts[num] = counts.GetValueOrDefault(num) + 1;

        return counts;
    }
}
